export const GLOSSARY_SHARD = Object.freeze({"coin-vs-token":{"slug":"coin-vs-token","cat":"basics","en":"Coin vs token","contentLocale":"ko","term":"코인과 토큰의 차이(Coin vs Token)","aka":["코인 토큰 차이","네이티브 코인"],"short":"코인은 자체 블록체인의 기본 자산(예: BTC, ETH)이고, 토큰은 다른 블록체인 위에서 스마트 컨트랙트로 발행된 자산(예: 이더리움 위의 USDT)입니다.","body":[["코인은 ",["블록체인","blockchain"]," 자체에 내장된 자산으로 수수료 지불, ",["채굴","mining"]," 보상, ",["스테이킹","staking"],"에 쓰입니다. ",["비트코인","bitcoin"]," 네트워크의 BTC, ",["이더리움","ethereum"],"의 ETH, 솔라나의 SOL이 대표적입니다. 그래서 네이티브 코인이라고도 부릅니다."],["토큰은 이미 있는 블록체인 위에 ",["스마트 컨트랙트","smart-contract"],"로 만든 자산입니다. 이더리움의 ERC-20 표준 토큰이 대표적이며, 스테이블코인, 거버넌스 토큰, 게임 아이템 토큰 등이 여기에 해당합니다. 토큰을 옮길 때도 수수료는 그 체인의 코인으로 냅니다."],"같은 토큰이 여러 체인에 발행되는 경우도 많습니다. USDT는 이더리움, 트론, 솔라나 등 여러 네트워크에 존재하고, 네트워크마다 컨트랙트 주소가 다릅니다. 실무에서는 코인과 토큰을 섞어서 코인이라고 부르는 경우가 흔합니다."],"example":"개인 지갑에 이더리움 네트워크 USDT 500개가 있고 ETH는 0개라고 해 보겠습니다. 이 USDT를 거래소로 보내려면 가스비로 예를 들어 0.001 ETH가 필요합니다. ETH 가격이 3,000 USDT라면 약 3 USDT어치 ETH를 먼저 지갑에 넣어야 전송이 가능합니다. 토큰 잔고가 충분해도 기본 코인이 없으면 움직일 수 없습니다.","mistakes":["토큰만 있으면 전송할 수 있다고 생각하고 가스비용 기본 코인을 준비하지 않습니다.","같은 USDT라도 네트워크가 다르면 서로 호환되지 않는다는 점을 놓칩니다.","지갑에 토큰을 추가할 때 공식이 아닌 컨트랙트 주소를 입력해 가짜 토큰을 표시합니다."],"faq":[{"q":"USDT는 코인인가요 토큰인가요?","a":"토큰입니다. 테더가 이더리움, 트론 등 여러 블록체인 위에 스마트 컨트랙트로 발행한 스테이블코인입니다."},{"q":"토큰이 나중에 코인이 될 수도 있나요?","a":"가능합니다. 프로젝트가 자체 메인넷을 출시하면 기존 토큰을 새 체인의 네이티브 코인으로 전환하는 경우가 있습니다."}],"title":"코인과 토큰의 차이는? 뜻과 구분법 정리","description":"코인과 토큰의 차이, 네이티브 코인과 ERC-20 토큰의 구분, 토큰 전송에 기본 코인이 필요한 이유를 예시로 설명합니다.","related":[["layer-1","레이어1(Layer 1, L1)","레이어1(L1)은 거래의 처리와 최종 확정을 스스로 담당하는 기본 블록체인으로, 비트코인, 이더리움, 솔라나처럼 자체 합의 방식과 네이티브 코인을 가집니다."],["smart-contract","스마트 컨트랙트(Smart Contract)","스마트 컨트랙트는 블록체인에 배포되어 미리 정한 조건이 충족되면 자동으로 실행되는 프로그램으로, 중개자 없이 거래와 규칙을 처리합니다."],["governance-token","거버넌스 토큰(Governance Token)","거버넌스 토큰은 보유량에 비례해 프로토콜이나 DAO의 주요 결정에 투표할 권리를 주는 토큰입니다."],["tokenomics","토크노믹스(Tokenomics)","토크노믹스는 토큰의 총발행량, 배분 비율, 언락 일정, 사용처, 소각과 인플레이션 규칙 등 토큰의 공급과 수요를 결정하는 경제 구조 전체를 말합니다."],["altcoin","알트코인(Altcoin)","알트코인은 비트코인을 제외한 나머지 암호화폐를 통틀어 부르는 말로, 이더리움, 솔라나, XRP 같은 대형 코인부터 소형 토큰까지 모두 포함합니다."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"memecoin":{"slug":"memecoin","cat":"basics","en":"Memecoin","contentLocale":"ko","term":"밈코인(Memecoin)","aka":["밈 코인","Memecoin","밈"],"short":"밈코인은 인터넷 밈이나 유머, 커뮤니티 문화를 바탕으로 만들어진 암호화폐로, 뚜렷한 기능보다 관심과 화제성이 가격을 크게 좌우하는 코인입니다.","body":["도지코인(DOGE)은 2013년 농담처럼 시작된 대표적인 밈코인이며, 이후 시바이누(SHIB), 페페(PEPE) 같은 코인이 뒤를 이었습니다. 최근에는 솔라나 같은 체인에서 누구나 몇 분 만에 밈코인을 발행할 수 있어 매일 수많은 토큰이 새로 나옵니다.",["밈코인은 SNS 분위기, 유명인 언급, 커뮤니티 결집에 따라 짧은 시간에 가격이 급등락합니다. 신규 밈코인 중 상당수는 ",["유동성","liquidity"],"이 얕아 큰 매도 한 번에 가격이 무너지기도 하고, 개발자가 유동성을 빼 가는 ",["러그풀","rug-pull"],"도 자주 발생합니다."],["밈코인을 볼 때는 유동성 규모, 상위 지갑의 보유 비율, 유동성 잠금 여부, ",["컨트랙트","smart-contract"]," 권한(민팅·거래 제한 기능)을 확인하는 것이 기본입니다. ",["거래소","centralized-exchange"],"에 상장된 밈코인도 ",["변동성","volatility"],"이 커서 ",["포지션 크기","position-sizing"],"를 작게 잡는 습관이 중요합니다."]],"example":"어떤 신규 밈코인의 유동성 풀에 20,000달러가 들어 있고, 상위 10개 지갑이 전체 공급의 60%를 갖고 있다고 해 보겠습니다. 200달러어치를 샀는데 상위 지갑 하나가 공급의 10%를 한꺼번에 팔면 가격이 절반 이하로 떨어질 수 있습니다. 이 경우 200달러는 순식간에 100달러 아래가 되며, 슬리피지 때문에 팔 때도 예상보다 적게 받습니다.","mistakes":["단가가 매우 낮다는 이유만으로 크게 오를 여지가 있다고 생각합니다.","소수 지갑에 물량이 집중된 신규 밈코인을 검증 없이 매수합니다.","SNS에서 본 컨트랙트 주소를 공식 주소인지 확인하지 않고 그대로 사용합니다."],"faq":[{"q":"밈코인과 일반 알트코인의 차이는 무엇인가요?","a":"밈코인도 알트코인의 한 종류지만, 기술이나 서비스보다 커뮤니티와 화제성이 가격의 중심이라는 점이 다릅니다. 그만큼 변동성이 극단적인 경우가 많습니다."},{"q":"밈코인 러그풀은 어떻게 피하나요?","a":"유동성이 잠겨 있는지, 개발자 지갑의 보유 비율이 높은지, 컨트랙트에 판매 제한이나 추가 발행 기능이 있는지 확인하는 것이 기본입니다. 완벽히 피할 수는 없으므로 감당 가능한 금액만 넣어야 합니다."}],"title":"밈코인이란? 뜻과 특징, 러그풀 주의점","description":"밈코인의 뜻과 대표 사례(도지코인 등), 급등락이 심한 이유, 유동성·지갑 집중도·러그풀 위험을 확인하는 방법을 설명합니다.","related":[["altcoin","알트코인(Altcoin)","알트코인은 비트코인을 제외한 나머지 암호화폐를 통틀어 부르는 말로, 이더리움, 솔라나, XRP 같은 대형 코인부터 소형 토큰까지 모두 포함합니다."],["rug-pull","러그풀(Rug Pull)","러그풀은 프로젝트 개발자나 운영자가 투자자의 돈이 모이면 유동성을 빼 가거나 토큰을 대량 매도하고 사라지는 사기 행위입니다."],["volatility","변동성(Volatility)","변동성은 일정 기간 동안 가격이 얼마나 크고 빠르게 오르내리는지를 나타내는 정도로, 변동성이 클수록 같은 기간에 가격이 더 크게 움직입니다."],["liquidity","유동성(Liquidity)","유동성은 원하는 수량의 자산을 가격을 크게 움직이지 않고 빠르게 사고팔 수 있는 정도를 뜻하며, 호가창의 두께와 스프레드로 확인할 수 있습니다."],["dex","탈중앙화 거래소(DEX)","탈중앙화 거래소(DEX)는 회사가 자산을 보관하지 않고 사용자가 개인 지갑에서 스마트 컨트랙트와 직접 토큰을 교환하는 거래소입니다."]],"lesson":null,"coin":{"slug":"dogecoin","name":"Dogecoin","symbol":"DOGE"},"tool":"/topics/meme-coins","cta":true},"hodl":{"slug":"hodl","cat":"basics","en":"HODL","contentLocale":"ko","term":"호들(HODL)","aka":["HODL","호들","장기 보유"],"short":"호들(HODL)은 단기 가격 변동에 흔들리지 않고 암호화폐를 오래 보유하는 전략이나 태도를 뜻하는 코인 커뮤니티 용어입니다.","body":[["호들은 2013년 한 ",["비트코인","bitcoin"]," 포럼 이용자가 hold를 HODL로 잘못 쓴 게시글에서 유행한 말입니다. 이후 Hold On for Dear Life라는 풀이가 붙어, 폭락에도 팔지 않고 버티는 장기 보유 문화를 뜻하게 됐습니다."],"호들 전략은 잦은 매매로 생기는 수수료와 감정적 실수를 줄일 수 있다는 장점이 있습니다. 하지만 어떤 코인이든 오래 들고만 있으면 회복된다는 보장은 없습니다. 상장 폐지되거나 프로젝트가 사라진 코인도 많기 때문에 무엇을 보유하는지가 핵심입니다.",["장기 보유를 할 때는 보관 방법도 중요합니다. ",["거래소","centralized-exchange"],"에 계속 맡길지, ",["개인 지갑","non-custodial-wallet"],"이나 ",["콜드월렛","cold-wallet"],"으로 옮길지 정하고, ",["시드 문구","seed-phrase"],"를 안전하게 백업해야 합니다. ",["분할 매수","dollar-cost-averaging"],"(적립식)와 함께 쓰는 경우가 많습니다."]],"example":"매달 30만 원씩 비트코인을 사서 호들한다고 가정해 보겠습니다. 첫 달 BTC가 1억 원이면 0.003 BTC, 둘째 달 8,000만 원이면 0.00375 BTC, 셋째 달 1억 2,000만 원이면 0.0025 BTC를 삽니다. 총 90만 원으로 0.00925 BTC를 모았고 평균 매수 단가는 약 9,730만 원입니다. 가격이 출렁여도 정해진 금액을 꾸준히 사면 평균 단가가 고르게 맞춰집니다.","mistakes":["프로젝트가 사실상 멈춘 코인까지 호들이라는 이유로 계속 들고 있습니다.","장기 보유 자산을 보안 설정 없이 거래소 계정에만 둡니다.","호들을 한다면서 생활비까지 넣어 급락 때 어쩔 수 없이 손절합니다."],"faq":[{"q":"HODL은 무슨 뜻인가요?","a":"hold의 오타에서 시작된 말로, 가격 변동에 흔들리지 않고 장기 보유한다는 뜻입니다. Hold On for Dear Life라는 풀이는 나중에 붙은 것입니다."},{"q":"호들은 언제까지 해야 하나요?","a":"정해진 기간은 없습니다. 보유 목적과 목표, 투자 기간을 미리 정해 두고, 보유 이유가 사라졌는지 주기적으로 점검하는 것이 좋습니다."}],"title":"호들(HODL)이란? 뜻과 장기 보유 전략","description":"호들(HODL)의 뜻과 유래, 장기 보유 전략의 장단점, 적립식 매수와 안전한 보관 방법을 계산 예시와 함께 정리합니다.","related":[["dollar-cost-averaging","적립식 분할 매수(DCA)","적립식 분할 매수(DCA)는 가격과 상관없이 정해진 금액을 일정한 간격으로 꾸준히 매수해 평균 매수 단가를 분산시키는 방법입니다."],["cold-wallet","콜드월렛(Cold Wallet, 콜드 스토리지)","콜드월렛은 개인 키를 인터넷과 분리된 환경에 보관해 온라인 해킹 위험을 크게 줄인 암호화폐 보관 방식입니다."],["bear-market","하락장(Bear Market, 베어장)","하락장은 가격이 비교적 긴 기간 동안 전반적으로 내려가고 투자 심리가 비관적인 시장 국면으로, 베어장 또는 약세장이라고도 부릅니다."],["volatility","변동성(Volatility)","변동성은 일정 기간 동안 가격이 얼마나 크고 빠르게 오르내리는지를 나타내는 정도로, 변동성이 클수록 같은 기간에 가격이 더 크게 움직입니다."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"liquidity-pool":{"slug":"liquidity-pool","cat":"defi","en":"Liquidity pool","contentLocale":"ko","term":"유동성 풀(Liquidity Pool)","aka":["LP 풀","풀","liquidity pool"],"short":"유동성 풀은 DEX에서 거래가 가능하도록 두 가지 이상의 토큰을 스마트 컨트랙트에 함께 예치해 둔 자금 저장소로, 공급자는 거래 수수료를 나눠 받습니다.","body":[[["유동성","liquidity"]," 공급자(LP)는 보통 두 토큰을 같은 가치로 넣습니다. 예를 들어 ETH와 USDC를 절반씩 예치하면 풀 지분을 나타내는 LP 토큰이나 포지션 NFT를 받습니다. 누군가 이 풀에서 거래할 때마다 내는 수수료가 지분 비율대로 쌓입니다."],["수익원은 거래 수수료와, 프로토콜이 따로 주는 보상 토큰입니다. 위험은 가격 변동으로 인한 ",["비영구적 손실","impermanent-loss"],", ",["스마트 컨트랙트","smart-contract"]," 해킹, 그리고 신규 토큰 풀이라면 ",["러그풀","rug-pull"],"입니다."],["풀 규모가 클수록 거래자는 ",["슬리피지","slippage"],"가 줄어 좋고, 공급자 입장에서는 수수료가 더 많은 사람에게 나뉩니다. 화면에 표시된 연 수익률은 과거 ",["거래량","trading-volume"]," 기준 추정치라 실제 결과와 다를 수 있습니다."]],"example":"총 가치 200만 USDC인 ETH-USDC 풀에 2만 USDC 어치를 넣었다고 가정합니다. 내 지분은 1%입니다. 하루 거래량이 100만 USDC이고 수수료율이 0.3%라면 하루 수수료는 3,000 USDC이며, 그중 1%인 30 USDC가 내 몫입니다. 이 상태가 1년 내내 이어지면 약 10,950 USDC지만, 거래량은 매일 바뀌고 ETH 가격이 움직이면 비영구적 손실이 이 수익을 상쇄할 수 있습니다.","mistakes":["화면의 높은 연 수익률이 그대로 유지된다고 생각합니다.","LP 토큰을 잃어버리거나 다른 곳에 보내 지분 회수 방법을 잃습니다.","유동성 잠금이 없는 신규 토큰 풀에 큰 금액을 공급합니다."],"faq":[{"q":"유동성 풀에 넣으면 원금이 보장되나요?","a":"보장되지 않습니다. 두 토큰 가격이 변하면 꺼낼 때 수량 비율이 달라지고, 컨트랙트 사고나 토큰 가격 하락으로 손실이 날 수 있습니다."},{"q":"LP 토큰은 무엇인가요?","a":"풀에서 내 지분을 증명하는 영수증 역할의 토큰입니다. 이 토큰을 반환해야 예치한 자산과 쌓인 수수료를 꺼낼 수 있습니다."}],"title":"유동성 풀이란? LP 수익 구조와 위험","description":"유동성 풀의 뜻, LP 토큰과 수수료 수익이 생기는 원리, 비영구적 손실과 러그풀 같은 위험을 예시로 설명합니다.","related":[["amm","자동화 마켓 메이커(AMM)","자동화 마켓 메이커(AMM)는 매수자와 매도자를 호가창에서 맞추는 대신 유동성 풀에 쌓인 두 토큰의 비율과 수학 공식으로 가격을 자동으로 정하는 거래 방식입니다."],["impermanent-loss","비영구적 손실(Impermanent Loss)","비영구적 손실은 유동성 풀에 넣은 두 토큰의 가격 비율이 변했을 때, 그냥 지갑에 들고 있었던 경우보다 풀에서 꺼낸 자산 가치가 줄어드는 현상입니다."],["yield-farming","일드 파밍(Yield Farming)","일드 파밍은 디파이 프로토콜에 자산을 예치하거나 유동성을 공급하고 그 대가로 이자, 수수료, 보상 토큰을 받아 수익을 쌓는 전략입니다."],["rug-pull","러그풀(Rug Pull)","러그풀은 프로젝트 개발자나 운영자가 투자자의 돈이 모이면 유동성을 빼 가거나 토큰을 대량 매도하고 사라지는 사기 행위입니다."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"perp-dex":{"slug":"perp-dex","cat":"defi","en":"Perp DEX (on-chain perpetuals)","contentLocale":"ko","term":"무기한 선물 DEX(Perp DEX)","aka":["퍼프 덱스","온체인 선물 거래소","perp DEX"],"short":"무기한 선물 DEX(Perp DEX)는 개인 지갑을 연결해 블록체인 위에서 무기한 선물을 레버리지로 거래하는 탈중앙화 거래소입니다.","body":[["하이퍼리퀴드(Hyperliquid), dYdX, GMX 등이 대표적입니다. 증거금을 ",["개인 지갑","non-custodial-wallet"],"에서 입금하고 롱이나 ",["숏 포지션","long-and-short"],"을 열며, ",["중앙화 거래소","centralized-exchange"],"처럼 ",["펀딩비","funding-rate"],"와 ",["강제청산","liquidation"],"이 있습니다. 하이퍼리퀴드처럼 자체 체인에 ",["호가창","order-book"],"을 올린 방식도 있고, GMX처럼 유동성 풀이 거래 상대가 되는 방식도 있습니다."],"장점은 계정 개설 없이 이용할 수 있고 거래 내역과 청산이 투명하게 공개된다는 점입니다. 대신 스마트 컨트랙트와 브리지 위험, 오라클 위험이 있고, 고객 지원이나 분쟁 해결 창구는 제한적입니다.","펀딩비 정산 주기, 최대 레버리지, 수수료, 청산 방식은 플랫폼마다 다릅니다. 많은 중앙화 거래소가 8시간마다 펀딩비를 정산하는 반면, 일부 Perp DEX는 1시간 단위로 정산하므로 계약 사양을 확인해야 합니다. 국내 원화 거래소는 선물 상품을 제공하지 않는다는 점도 알아 두면 좋습니다."],"example":"Perp DEX에 1,000 USDC를 입금하고 BTC가 60,000 USDC일 때 5배 레버리지로 5,000 USDC 규모의 롱을 열었다고 가정합니다. 포지션 수량은 약 0.0833 BTC입니다. 1시간 펀딩비가 0.001%라면 시간마다 약 0.05 USDC를 내고, 하루면 약 1.2 USDC입니다. BTC가 10% 떨어지면 손실은 약 500 USDC로 증거금의 절반이 사라지고, 유지 증거금 기준에 따라 그보다 조금 더 내려가면 강제청산됩니다.","mistakes":["탈중앙화라는 이유로 강제청산이 없거나 덜 엄격하다고 생각합니다.","펀딩비 정산 주기가 중앙화 거래소와 같다고 가정합니다.","증거금을 옮기기 위해 쓴 브리지와 체인 위험을 계산에 넣지 않습니다."],"faq":[{"q":"Perp DEX와 중앙화 선물 거래소의 차이는 무엇인가요?","a":"Perp DEX는 개인 지갑으로 직접 거래하고 기록이 체인에 공개되며, 중앙화 거래소는 회사가 자산을 보관하고 엔진을 운영합니다. 위험 구조와 지원 범위가 다릅니다."},{"q":"Perp DEX에서도 청산되나요?","a":"네. 증거금이 유지 증거금 아래로 내려가면 강제청산되며, 청산 가격과 수수료 방식은 플랫폼마다 다릅니다."}],"title":"Perp DEX란? 온체인 무기한 선물 거래소","description":"Perp DEX(무기한 선물 DEX)의 뜻과 작동 방식, 하이퍼리퀴드 같은 예시, 펀딩비와 강제청산 등 중앙화 거래소와의 차이를 설명합니다.","related":[["perpetual-futures","무기한 선물(Perpetual Futures)","무기한 선물은 만기일 없이 원하는 만큼 포지션을 유지할 수 있는 선물 계약으로, 펀딩비를 주고받아 가격이 현물 가격 근처에 머물도록 설계되어 있습니다."],["dex","탈중앙화 거래소(DEX)","탈중앙화 거래소(DEX)는 회사가 자산을 보관하지 않고 사용자가 개인 지갑에서 스마트 컨트랙트와 직접 토큰을 교환하는 거래소입니다."],["funding-rate","펀딩비(Funding Rate)","펀딩비는 무기한 선물에서 롱과 숏 포지션 보유자가 일정 간격마다 서로 주고받는 비용으로, 선물 가격이 현물 가격에서 크게 벗어나지 않도록 하는 장치입니다."],["non-custodial-wallet","비수탁형 지갑(Non-custodial Wallet, 개인 지갑)","비수탁형 지갑은 거래소 같은 제3자가 아니라 사용자 본인이 개인 키와 시드 문구를 직접 보관하고 관리하는 암호화폐 지갑입니다."]],"lesson":null,"coin":{"slug":"hyperliquid","name":"Hyperliquid","symbol":"HYPE"},"tool":"/funding-rates","cta":false},"copy-trading":{"slug":"copy-trading","cat":"exchange-features","en":"Copy trading","contentLocale":"ko","term":"카피 트레이딩(Copy trading)","aka":["카피트레이딩","복사 거래","Copy trading"],"short":"카피 트레이딩은 다른 트레이더(리드 트레이더)의 매매를 내 계정에서 정해진 비율이나 금액으로 자동으로 따라 하는 거래소 기능입니다.","body":[["OKX, Bybit, Bitget 같은 ",["거래소","centralized-exchange"],"가 선물과 현물 카피 트레이딩을 제공합니다. 리드 트레이더 목록에서 수익률, 최대 낙폭, 운용 기간, 팔로워 수를 보고 한 명을 고른 뒤, 투자 금액과 복사 방식을 정하면 그 트레이더가 진입하고 청산할 때 내 계정에서도 같은 방향으로 주문이 나갑니다."],["수익이 나면 보통 수익의 일정 비율을 리드 트레이더에게 성과 보수로 나눕니다. 비율과 정산 방식은 거래소마다 다릅니다. 선물 카피라면 리드 트레이더가 쓰는 ",["레버리지","leverage"],"가 그대로 적용되거나, 내가 직접 정한 레버리지가 적용될 수 있으니 설정 화면을 꼭 확인해야 합니다."],"과거 수익률은 미래를 보장하지 않습니다. 짧은 기간에 높은 수익률을 낸 트레이더는 큰 레버리지를 썼을 가능성이 크고, 진입 시점이 달라 나의 실제 체결가가 리드 트레이더와 다를 수 있습니다. 1회 손실 한도와 전체 손절 금액을 먼저 정하는 것이 기본입니다."],"example":["리드 트레이더를 1,000 USDT로 따라 하고, 성과 보수가 10%라고 가정합니다. 한 달 동안 리드 트레이더가 계좌 대비 15% 수익을 냈다면 내 수익은 150 ",["USDT","usdt"],", 보수 15 USDT를 떼면 135 USDT가 남습니다. 반대로 같은 기간 30% 손실이 났다면 300 USDT를 잃고 보수는 없습니다. 최대 손실 한도를 200 USDT로 걸어 두었다면 손실이 그 선에서 멈춥니다."],"mistakes":["최근 7일 수익률 순위 1위만 보고 리드 트레이더를 고릅니다.","리드 트레이더의 레버리지가 내 계정에도 그대로 적용된다는 점을 확인하지 않습니다.","손실 한도를 걸지 않고 전체 자금을 한 명에게 맡깁니다."],"faq":[{"q":"카피 트레이딩은 손실이 나도 보수를 내나요?","a":"일반적으로 성과 보수는 수익이 났을 때만 냅니다. 다만 정산 기준과 주기는 거래소마다 다르므로 상품 설명을 확인해야 합니다."},{"q":"카피 트레이딩 도중 직접 청산할 수 있나요?","a":"대부분의 거래소에서 개별 포지션을 수동으로 닫거나 복사를 중단할 수 있습니다. 중단 시 열린 포지션 처리 방식은 설정에 따라 다릅니다."}],"title":"카피 트레이딩이란? 작동 방식과 수익·손실 계산","description":"카피 트레이딩의 뜻, 리드 트레이더를 고르는 기준, 성과 보수와 손실 한도 계산 예시를 설명합니다.","related":[["perpetual-futures","무기한 선물(Perpetual Futures)","무기한 선물은 만기일 없이 원하는 만큼 포지션을 유지할 수 있는 선물 계약으로, 펀딩비를 주고받아 가격이 현물 가격 근처에 머물도록 설계되어 있습니다."],["leverage","레버리지(Leverage)","레버리지는 맡긴 증거금보다 몇 배 큰 규모의 포지션을 거래하는 것으로, 수익과 손실이 모두 그 배수만큼 커지고 강제청산 위험도 함께 커집니다."],["risk-reward-ratio","손익비(Risk-Reward Ratio)","손익비는 한 번의 거래에서 감수하는 손실 폭(진입가와 손절가의 차이)과 기대하는 수익 폭(진입가와 익절가의 차이)을 비교한 비율입니다."],["grid-trading-bot","그리드 트레이딩 봇","그리드 트레이딩 봇은 정해진 가격 범위를 여러 칸으로 나눠 낮은 칸에서 사고 높은 칸에서 파는 지정가 주문을 자동으로 반복하는 매매 도구입니다."]],"lesson":null,"coin":null,"tool":"/compare","cta":true}});
